// Domain types for the OKRs module.
//
// These live here rather than in src/types/database.ts because that file is
// generated by `supabase gen types` and must never be hand-edited. The service
// layer is untyped (`type Client = any`, as in src/services/ministries.ts), so
// these describe the shapes the pages and components actually pass around.

export const OKR_STATUSES = [
  "not_started",
  "in_progress",
  "moving_forward",
  "stuck",
  "complete",
] as const;

export type OkrStatus = (typeof OKR_STATUSES)[number];

export type OkrScope = "ministry" | "individual";

export interface OkrCycle {
  id: string;
  name: string;
  slug: string;
  starts_on: string;
  ends_on: string;
  is_current: boolean;
}

export interface OkrKeyResult {
  id: string;
  objective_id: string;
  position: number;
  label: string | null;
  description: string;
  notes: string | null;
  timeline: string | null;
  owner_note: string | null;
  metric_unit: string | null;
  metric_start: number | null;
  metric_target: number | null;
  current_status: OkrStatus;
  current_value: number | null;
  last_checkin_at: string | null;
}

/**
 * A group that writes OKRs but is not a staff ministry — The Watchmen, Hope
 * Again, Old Age Homes, Evangelism, Brave Love. No roster, no leaders: if one
 * ever needs those it should become a staff ministry instead.
 */
export interface OkrTeam {
  id: string;
  name: string;
  slug: string;
  description: string | null;
  is_active: boolean;
  sort_order: number;
}

export interface OkrObjective {
  id: string;
  cycle_id: string;
  scope: OkrScope;
  /** Exactly one of staff_ministry_id / okr_team_id is set. */
  staff_ministry_id: string | null;
  okr_team_id: string | null;
  subcategory_id: string | null;
  owner_user_id: string | null;
  position: number;
  title: string;
  description: string | null;
  /** Standing context for the objective as a whole (migration 197). */
  notes: string | null;
  /** Who is carrying it — a name or a team. Not the same thing as notes. */
  owner_note: string | null;
  timeline: string | null;
  is_archived: boolean;
  okr_key_results: OkrKeyResult[];
}

export interface OkrCheckin {
  id: string;
  key_result_id: string;
  checkin_on: string;
  status: OkrStatus;
  value: number | null;
  comment: string | null;
  author_id: string;
  created_at: string;
  /** Hydrated separately via the admin client — see the users-RLS note. */
  author_name?: string | null;
}

/**
 * An owning group as the wall sees it — a staff ministry or an OKR-only team.
 * The wall does not care which; only edit rights do.
 */
export interface OkrOwner {
  id: string;
  name: string;
  slug: string;
  kind: "ministry" | "team";
}

/** Per-owner roll-up for the OKR wall. */
export interface OkrOwnerSummary extends OkrOwner {
  objectives: number;
  keyResults: number;
  byStatus: Record<OkrStatus, number>;
}

/** One recorded edit. Written only by the triggers in migration 197. */
export interface OkrEvent {
  id: string;
  key_result_id: string | null;
  objective_id: string | null;
  action: "created" | "updated" | "deleted";
  field: string | null;
  old_value: string | null;
  new_value: string | null;
  actor_id: string | null;
  created_at: string;
  /** Hydrated separately via the admin client — see the users-RLS note. */
  actor_name?: string | null;
}

/**
 * One key result's story: progress check-ins and edits in a single stream.
 *
 * They stay separate in the database — a check-in is a deliberate statement
 * with a status and a date the author chose, an event is a fact the database
 * observed — but they answer the same question, so the drawer interleaves
 * them. Ordered by `at` (the row's created_at), which is also what
 * refresh_okr_key_result_state() uses for last_checkin_at.
 */
export type OkrHistoryEntry =
  | { kind: "checkin"; at: string; author: string | null; checkin: OkrCheckin }
  | { kind: "event"; at: string; author: string | null; event: OkrEvent };
